/**
 * Singleton PhysicsFrustum instance for the physics worker.
 * Import this for most use cases.
 */
export const physicsFrustum: PhysicsFrustum;
/**
 * PhysicsFrustum - Camera frustum culling for physics collision.
 *
 * Provides frustum-based visibility testing for physics bodies.
 * Use the exported singleton `physicsFrustum` for most cases.
 */
export class PhysicsFrustum {
    frustum: any;
    projectionMatrix: any;
    viewMatrix: any;
    viewProjectionMatrix: any;
    _cameraPosition: any;
    _cameraQuaternion: any;
    _cameraScale: any;
    _cameraMatrix: any;
    _expandedBox: any;
    _worldBox: any;
    margin: number;
    enabled: boolean;
    _visibleStatics: any[];
    _visibleKinematics: any[];
    _visibleZones: any[];
    /**
     * Configure frustum parameters.
     *
     * @param {Object} config - Configuration object.
     * @param {number} [config.margin] - Padding in world units to expand bounding boxes.
     * @param {boolean} [config.enabled] - Enable/disable frustum culling.
     * @returns {PhysicsFrustum} This instance for chaining.
     */
    set(config: {
        margin?: number;
        enabled?: boolean;
    }): PhysicsFrustum;
    /**
     * Update frustum planes from current camera state in sharedCamera.
     * Call once per physics frame before any visibility tests.
     *
     * @returns {PhysicsFrustum} This instance for chaining.
     */
    setFromCamera(): PhysicsFrustum;
    /**
     * Test if a bounding box intersects the frustum.
     *
     * @param {THREE.Box3} box - Bounding box to test.
     * @returns {boolean} True if box is visible in frustum.
     */
    intersectsBox(box: THREE.Box3): boolean;
    /**
     * Test if a physics body is visible in the frustum.
     *
     * @param {Object} body - Physics body with bvh.geometry.boundingBox.
     * @param {boolean} [isKinematic=false] - Whether this is a kinematic body that needs world transform.
     * @returns {boolean} True if body is visible.
     */
    intersectsBody(body: any, isKinematic?: boolean): boolean;
    /**
     * Get all static bodies visible in the current frustum.
     *
     * @returns {Array} Array of visible static body references.
     */
    getVisibleStatics(): any[];
    /**
     * Get all kinematic bodies visible in the current frustum.
     *
     * @returns {Array} Array of visible kinematic body references.
     */
    getVisibleKinematics(): any[];
    /**
     * Get all zone bodies visible in the current frustum.
     *
     * @returns {Array} Array of visible zone body references.
     */
    getVisibleZones(): any[];
}
